def _cache_matches_origin(original_graph, final_graph, row):
    origin = row.get('origin')
    if origin is None:
        return False
    old_row = original_graph.get(origin)
    if old_row is None:
        return False
    if old_row['source'] != row['source'] or sorted(old_row['deps']) != row['deps']:
        return False
    for dep in row['deps']:
        if final_graph[dep].get('origin') != dep:
            return False
    return True


def _reconcile_final_graph(original_graph, final_graph):
    changed_ids = set()
    invalidated = set()
    for name in set(original_graph) | set(final_graph):
        before = original_graph.get(name)
        after = final_graph.get(name)
        if _definition_changed(before, after):
            changed_ids.add(name)
    for new_id, row in final_graph.items():
        if not _cache_matches_origin(original_graph, final_graph, row):
            row['digest'] = None
            invalidated.add(new_id)
    reverse_dirty = closure(final_graph, invalidated, reverse=True) if invalidated else set()
    for name in reverse_dirty:
        final_graph[name]['digest'] = None
    return sorted(changed_ids), sorted(invalidated | reverse_dirty)


def _finalize_origins(graph):
    for name, row in graph.items():
        if row.get('origin') is None:
            row['origin'] = name

